import("stdfaust.lib");
process = left, right with {
    inL = _;
    inR = _;
    dtime = hslider("Delay Time [unit:ms]", 300, 1, 2000, 1) * 0.001 : si.smoo;
    fb    = hslider("Feedback", 0.5, 0, 0.95, 0.01) : si.smoo;
